"""Collect actual verified release outputs without substituting an older binary."""
from pathlib import Path
import json,hashlib,shutil,datetime,zipfile
root=Path(__file__).resolve().parents[1]
version=json.loads((root/'desktop/package.json').read_text())['version']
source_hash=hashlib.sha256((root/'index.html').read_bytes()).hexdigest()
android=json.loads((root/'android/dist/build-manifest.json').read_text())
assert android['version']==version and android['sourceSHA256']==source_hash
files=[('Windows Customer',f'desktop/dist/setup/KP-Master-Setup-{version}-x64.exe',f'KP-Master-Customer-Setup-{version}-x64.exe'),('Windows Owner',f'desktop/owner-edition/dist/setup/KP-Master-Owner-Setup-{version}-x64.exe',f'KP-Master-Owner-Setup-{version}-x64.exe'),('Windows Owner Activation',f'desktop/owner/dist/setup/KP-Master-Owner-Activation-Setup-{version}-x64.exe',f'KP-Master-Owner-Activation-Setup-{version}-x64.exe')]
for edition in ['Owner','Customer']:files.append(('Android '+edition,f'android/dist/KP-Master-{edition}-{version}.apk',f'KP-Master-{edition}-{version}.apk'))
artifacts=[]
for edition,source,name in files:
 shutil.copyfile(root/source,root/name)
 artifacts.append({'edition':edition,'file':name})
for edition in ['Owner','Customer']:artifacts.append({'edition':edition+' Web','file':f'KP-MASTER-{edition}-Web-{version}.zip'})
artifacts.extend([{'edition':'HTML and available backup data','file':f'KP-MASTER-HTML-All-Data-{version}.zip'},{'edition':'Standalone HTML','file':f'KP-MASTER-Updated-HTML-{version}.zip'},{'edition':'Tutorial PDF','file':f'docs/KP-MASTER-User-Tutorial-{version}.pdf'}])
for item in artifacts:
 p=root/item['file'];item.update(bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest())
 assert item['bytes']<100*1024*1024,'Artifact exceeds GitHub ordinary-file limit: '+item['file']
meta={'version':version,'builtAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'sourceHTMLSHA256':source_hash,'artifacts':artifacts,'android':{'versionCode':android['versionCode'],'signingCertificateSHA256':android['signingCertificateSHA256'],'signingContinuity':'Same certificate as the previously released fresh-install 1.2.8 edition. Original older-certificate apps require backup and reinstall.','minimumAndroid':'9','physicalDeviceTested':False},'iphone':{'nativeIPA':'not built','reason':'macOS/Xcode and Apple signing/provisioning are unavailable in this Linux workspace. APKs cannot install on iPhone.','alternative':'Owner/Customer web archives can be hosted over HTTPS; browser/device testing on iPhone has not been performed.'},'backup':{'included':'Current HTML, available data/vendor/docs files and workspace backup folders; per-file checksums in the ZIP.','unavailable':'Actual saved kundali and report-photo folders contain instructions only. Browser/device-local data and private signing/activation keys are not in this archive.'},'validation':{'desktopUnitTestFiles':40,'androidLicenceAssertions':26,'androidDemo':'passed','mobileBrowserBackupExportsPDF':'passed','androidSignatureAndAlignment':'passed both','windowsInstallerPayloadAndAsarParity':'passed all three','transitOnePassAndPrint':'passed','activationExpiryUTC':'desktop exact boundary and Android dated/expired/future issue checks passed','historyReset':'first 1.2.11 launch only; local recovery copy retained','nativeWindowsInstallation':False,'physicalAndroidDevice':False}}
(root/f'KP-MASTER-RELEASE-{version}.json').write_text(json.dumps(meta,indent=2)+'\n')
(root/f'KP-MASTER-{version}-SHA256SUMS.txt').write_text(''.join(a['sha256']+'  '+a['file']+'\n' for a in artifacts))
lines=[f'# KP MASTER {version}', '', 'Release date: 20 October 2026. Event significators mode now follows the Transit Reader rule only: selected moving planets are checked through event-significator star AND sub lords. DBA supplies dates only; Rashi, transit houses, RP and additional planet gates do not filter this mode. One scan produces daily ephemeris-style rows and exact simultaneous matching windows; the pictured rule-summary panel is removed. Rule-matching windows do not guarantee a real event date.', '', '| Edition | Download |', '| --- | --- |']
lines.extend('| '+a['edition']+' | ['+a['file']+']('+a['file']+') |' for a in artifacts)
lines.extend(['','Windows: Windows 10/11 x64. Owner calculator, activated Customer calculator and the separate Owner Activation tool retain their existing identities. Installers are unsigned; native Windows installation has not been run here.','','Activation: existing signing identities and customer keys are preserved. Dated keys expire at 23:59:59.999 UTC on the chosen date. Customer access is rechecked while open. On first launch of the 1.2.11 activation tool, the visible history is cleared once; its previous file is retained locally as a recovery copy. Newly issued records persist on later launches.','','Android: Android 9+. Version '+version+', versionCode '+str(android['versionCode'])+'. Uses the same certificate as the prior fresh-install 1.2.8 APKs, so those installations can update. For an app with the older original certificate, export your backup before uninstalling/reinstalling. Physical-phone installation has not been tested here.','','iPhone: no native IPA is included. Native packaging requires macOS/Xcode and Apple signing/provisioning. APK files are Android-only. The web editions require HTTPS hosting for iPhone use and have not been tested on a physical iPhone. Keep the unlocked Owner edition private.','','HTML backup: extract completely and open KP-MASTER/index.html. The ZIP includes all available reference/data sources and a per-file checksum manifest. The workspace Kundali Backup and Report Photos folders contain instructions only; browser/device-local files and private keys are unavailable and are not included.','','Checks: 40 desktop unit-test files; Android licence/demo tests; APK signatures/alignment and byte-parity; mobile browser exports/backups/A4 PDF; all three Windows installer payloads and packaged source verified.'])
(root/f'KP-MASTER-RELEASE-{version}.md').write_text('\n'.join(lines)+'\n')
print(json.dumps({'version':version,'artifacts':[(a['file'],a['bytes']) for a in artifacts]}))
